ALTER TABLE public.products
  ADD CONSTRAINT products_published_requires_image
  CHECK (NOT is_published OR image_url IS NOT NULL);

ALTER TABLE public.blog_posts
  ADD CONSTRAINT blog_posts_published_requires_content
  CHECK (
    status <> 'published'
    OR (published_at IS NOT NULL AND length(btrim(body_markdown)) > 0)
  );

